response:
**Gates before launch.** I assumed the trial runner is `python3 spe/evals/harness/run_trial.py` with the same flags round 3 used. I also assumed the tickets are at `spe/evals/tasks/tickets/t001.json` through `t050.json`. The script's Preflight phase checks that both exist. Gate 1: `git status` is clean, and `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md` exits 0. That proves the predictions were locked before any trial ran. Gate 2: I run `grade.py` on two fixtures. A copy of `answers.json` used as model output must score 100%. A copy with shuffled labels must score near chance. Gate 3: I give `judge.md` three round 3 replies that I already scored by hand, and the judge must match all three. Gate 4: I run the script with `mode: 'smoke'`. That is 2 tickets, 1 trial, and both configs, written to `spe/evals/runs/r04-smoke/`. I read the real cost of that run and pass it in as `trialUsd` and `judgeUsd`. Full mode makes 100 trial agents, 500 runner calls, and 500 Opus judge calls. I launch only if that projects to $34 or less, which leaves $6 of the $40 cap for retries. If the projection is higher, I stop and bring it to you. I will not batch the judge or cut trials to fit, because that would change the approved plan. Gate 5: I save the script as `spe/evals/harness/r04-workflow.js` and make a local commit for this step. I do not push.

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4. Configs B and C2, 50 tickets x 5 trials. Code grader on label.category and label.priority, Opus judge on reply tone, $40 spend cap.',
  phases: [
    { title: 'Preflight' },
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Report' },
  ],
};

// ---- Settings -------------------------------------------------------------
const MODE = args.mode ?? 'smoke';            // 'smoke' first, then 'full'
const FULL = MODE === 'full';
const CAP_USD = 40;
const CONFIGS = ['B', 'C2'];
const TRIALS = FULL ? 5 : 1;
const MODEL = args.model ?? 'opus';           // never haiku
const RUNNER = args.runner ?? 'python3 spe/evals/harness/run_trial.py';
const RUN_DIR = FULL ? 'spe/evals/runs/r04' : 'spe/evals/runs/r04-smoke';
const TICKETS = args.tickets ?? (FULL
  ? Array.from({ length: 50 }, (_, i) => 't' + String(i + 1).padStart(3, '0'))
  : ['t001', 't002']);

// Per-call cost estimates measured in the smoke run. Full mode refuses to start without them.
const TRIAL_USD = Number(args.trialUsd ?? (FULL ? NaN : 1));
const JUDGE_USD = Number(args.judgeUsd ?? (FULL ? NaN : 1));
if (FULL && !(TRIAL_USD > 0 && JUDGE_USD > 0)) {
  throw new Error('Full mode needs args.trialUsd and args.judgeUsd from the smoke run.');
}
if (FULL && TICKETS.length !== 50) {
  throw new Error(`Plan says 50 tickets. Got ${TICKETS.length}.`);
}

// ---- Spend cap ------------------------------------------------------------
// Reserve the estimate before each agent call. JS is single-threaded, so the check and add are atomic.
let spent = 0;
const skipped = [];
function reserve(usd, what) {
  if (spent + usd > CAP_USD) {
    skipped.push(what);
    log(`CAP: skipped ${what}. Reserved $${spent.toFixed(2)} of $${CAP_USD}.`);
    return false;
  }
  spent += usd;
  return true;
}

// ---- Schemas --------------------------------------------------------------
const PREFLIGHT_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    problems: { type: 'array', items: { type: 'string' } },
  },
  required: ['ok', 'problems'],
};

const TRIAL_SCHEMA = {
  type: 'object',
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          trial: { type: 'integer' },
          ok: { type: 'boolean' },
          out_path: { type: 'string' },
          reply: { type: 'string' },
          error: { type: 'string' },
        },
        required: ['trial', 'ok', 'out_path', 'reply'],
      },
    },
  },
  required: ['trials'],
};

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    score: { type: 'number' },
    pass: { type: 'boolean' },
    rationale: { type: 'string' },
  },
  required: ['score', 'pass', 'rationale'],
};

const GRADE_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    exit_code: { type: 'integer' },
    per_config: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          config: { type: 'string' },
          n_graded: { type: 'integer' },
          category_acc: { type: 'number' },
          priority_acc: { type: 'number' },
          both_acc: { type: 'number' },
        },
        required: ['config', 'n_graded', 'category_acc', 'priority_acc', 'both_acc'],
      },
    },
    stderr: { type: 'string' },
  },
  required: ['ok', 'exit_code', 'per_config'],
};

const WRITE_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    judge_lines: { type: 'integer' },
    error: { type: 'string' },
  },
  required: ['ok', 'judge_lines'],
};

// ---- Preflight ------------------------------------------------------------
phase('Preflight');
log(`Mode ${MODE}. ${CONFIGS.length} configs x ${TICKETS.length} tickets x ${TRIALS} trials. Output ${RUN_DIR}.`);

const pre = await agent(
  `Check each item below from the repo root and report every problem you find.
The only change you may make is creating ${RUN_DIR}/raw if it is missing. Change nothing else.
1. These files exist: spe/evals/graders/grade.py, spe/evals/graders/judge.md, spe/evals/tasks/answers.json, spe/predictions/r04.yaml, spe/plans/r04.md.
2. The runner script named in this command exists: ${RUNNER}
3. A ticket file exists at spe/evals/tasks/tickets/<id>.json for each id: ${TICKETS.join(', ')}.
4. spe/evals/tasks/answers.json has an entry for every id in item 3.
5. \`git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md\` exits 0.
6. ${RUN_DIR}/raw is missing or empty. If it has files in it, report that as a problem and do not delete them.
Set ok to true only if every item passes.`,
  { label: 'preflight', phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: MODEL },
);
if (!pre.ok) {
  throw new Error('Preflight failed: ' + pre.problems.join(' | '));
}

// ---- Trials + judge -------------------------------------------------------
phase('Trials');

// Alternate configs by ticket so drift over time hits both configs the same way.
const cells = [];
for (const ticket of TICKETS) {
  for (const config of CONFIGS) cells.push({ config, ticket });
}

function outPath(config, ticket, n) {
  return `${RUN_DIR}/raw/${config}__${ticket}__t${n}.json`;
}

async function runCell(cell) {
  const what = `${cell.config}/${cell.ticket}`;
  if (!reserve(TRIALS * TRIAL_USD, `trials ${what}`)) {
    return { ...cell, skipped: true, trials: [] };
  }
  const cmds = Array.from({ length: TRIALS }, (_, i) =>
    `${RUNNER} --config ${cell.config} --ticket ${cell.ticket} --trial ${i + 1} --out ${outPath(cell.config, cell.ticket, i + 1)}`,
  ).join('\n');

  const res = await agent(
    `You run trials for SPE round 4. You do not grade or judge anything.
Do not edit any config, grader, ticket, answer, prediction, or plan file.
Run these commands one at a time from the repo root, in this order:
${cmds}
Each command writes one JSON file at its --out path.
After each command, run \`jq -r .reply <out path>\` and copy its stdout into "reply" exactly. Do not trim, fix, or rewrite it.
If a command exits nonzero, retry it once. If the retry also fails, set ok to false, set reply to "", and put the last 20 lines of stderr in "error".
Return one entry per trial, numbered 1 to ${TRIALS}.`,
    { label: `trial ${what}`, phase: 'Trials', schema: TRIAL_SCHEMA, model: MODEL },
  );
  return { ...cell, skipped: false, trials: res.trials };
}

async function judgeCell(cell) {
  if (cell.skipped) return cell;
  const judged = await parallel(cell.trials.map((t) => async () => {
    if (!t.ok) return { ...t, judge: null };
    if (!reserve(JUDGE_USD, `judge ${cell.config}/${cell.ticket}/t${t.trial}`)) {
      return { ...t, judge: null };
    }
    // The judge sees the ticket and the reply. It never sees the config name or the run file.
    const j = await agent(
      `Read spe/evals/graders/judge.md and apply its tone rubric exactly.
Read spe/evals/tasks/tickets/${cell.ticket}.json for context.
Do not open anything under spe/evals/runs/, spe/evals/configs/, spe/predictions/, or spe/plans/.
Score only the tone of the reply below. Do not score category or priority.
<reply>
${t.reply}
</reply>`,
      { label: `judge ${cell.ticket}`, phase: 'Trials', schema: JUDGE_SCHEMA, model: 'opus' },
    );
    return { ...t, judge: j };
  }));
  return { ...cell, trials: judged };
}

const results = await pipeline(cells, runCell, judgeCell);
log(`Trials done. Reserved $${spent.toFixed(2)} of $${CAP_USD}. Skipped ${skipped.length} calls.`);

// ---- Code grader ----------------------------------------------------------
phase('Grade');
const grade = await agent(
  `Run this command from the repo root. Do nothing else.
python3 spe/evals/graders/grade.py --runs ${RUN_DIR}/raw --answers spe/evals/tasks/answers.json --out ${RUN_DIR}/grades.json
Then read ${RUN_DIR}/grades.json and copy the per-config numbers exactly as the file states them. Do not recompute or round them.
If the command exits nonzero, set ok to false, report the exit code, and put the last 20 lines of stderr in "stderr".`,
  { label: 'grade.py', phase: 'Grade', schema: GRADE_SCHEMA, model: MODEL },
);
if (!grade.ok) log(`GRADER FAILED (exit ${grade.exit_code}). ${grade.stderr ?? ''}`);

// ---- Report ---------------------------------------------------------------
phase('Report');

const rows = results.flatMap((c) => c.trials.map((t) => ({
  config: c.config,
  ticket: c.ticket,
  trial: t.trial,
  ok: t.ok,
  error: t.error ?? null,
  tone_score: t.judge ? t.judge.score : null,
  tone_pass: t.judge ? t.judge.pass : null,
  tone_rationale: t.judge ? t.judge.rationale : null,
})));

const perConfig = CONFIGS.map((config) => {
  const mine = rows.filter((r) => r.config === config);
  const judged = mine.filter((r) => r.tone_score !== null);
  const g = (grade.per_config ?? []).find((p) => p.config === config) ?? null;
  return {
    config,
    trials_planned: TICKETS.length * TRIALS,
    trials_run: mine.length,
    trials_failed: mine.filter((r) => !r.ok).length,
    tone_judged: judged.length,
    tone_pass_rate: judged.length ? judged.filter((r) => r.tone_pass).length / judged.length : null,
    tone_mean: judged.length ? judged.reduce((s, r) => s + r.tone_score, 0) / judged.length : null,
    code_grade: g,
  };
});

const summary = {
  round: 4,
  mode: MODE,
  run_dir: RUN_DIR,
  configs: CONFIGS,
  tickets: TICKETS.length,
  trials_per_cell: TRIALS,
  spend_cap_usd: CAP_USD,
  spend_reserved_usd_estimate: Number(spent.toFixed(2)),
  per_call_estimates_usd: { trial: TRIAL_USD, judge: JUDGE_USD },
  skipped_calls: skipped,
  grader_ok: grade.ok,
  per_config: perConfig,
  complete: skipped.length === 0 && grade.ok && rows.every((r) => r.ok),
};

const judgeJsonl = rows.map((r) => JSON.stringify(r)).join('\n');
const write = await agent(
  `Write two files from the repo root. Write the content exactly as given and change nothing else.
File 1: ${RUN_DIR}/judge.jsonl with this content:
<content>
${judgeJsonl}
</content>
File 2: ${RUN_DIR}/run-summary.json with this content, pretty-printed with 2-space indent:
<content>
${JSON.stringify(summary)}
</content>
Then run \`wc -l < ${RUN_DIR}/judge.jsonl\` and \`jq . ${RUN_DIR}/run-summary.json > /dev/null\`. Report the line count. Set ok to false if jq fails.`,
  { label: 'write results', phase: 'Report', schema: WRITE_SCHEMA, model: MODEL },
);
if (!write.ok) log(`WRITE FAILED: ${write.error ?? 'unknown'}`);

for (const p of perConfig) {
  log(`${p.config}: ${p.trials_run - p.trials_failed}/${p.trials_planned} trials ok. ` +
      `cat ${p.code_grade?.category_acc ?? 'n/a'}, pri ${p.code_grade?.priority_acc ?? 'n/a'}, ` +
      `tone pass ${p.tone_pass_rate ?? 'n/a'}.`);
}
log(summary.complete ? 'Run complete.' : 'Run INCOMPLETE. Check skipped_calls, failed trials, and grader status before comparing to spe/predictions/r04.yaml.');

return summary;
```
